insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('project-roles-03','project-roles',2,'3.1','Where a product owner role is used, which contribution is most characteristic?','[{"id":"a","text":"Clarifying product needs and ordering backlog priorities."},{"id":"b","text":"Automatically owning the organisation’s entire investment portfolio."},{"id":"c","text":"Replacing all project governance."},{"id":"d","text":"Providing independent audit in every project."}]'::jsonb,'a','A product owner represents product priorities and helps clarify what should be developed. Portfolio decisions, governance and independent assurance are different responsibilities and do not automatically belong to that role.')
