insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('project-roles-04','project-roles',2,'3.1','A team needs help applying consistent reporting standards across several projects. Which role is particularly suited to providing that support?','[{"id":"a","text":"The project management office, within its agreed remit."},{"id":"b","text":"Every end user acting as the investment sponsor."},{"id":"c","text":"The product owner replacing all governance bodies."},{"id":"d","text":"The customer receiving no delivery information."}]'::jsonb,'a','A PMO can support common methods, reporting and coordination. Its authority depends on the organisation. Users and product owners have other contributions and do not automatically replace sponsorship or governance.')
