insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('business-case-04','business-case',2,'4.7','Which arrangement makes a promised benefit most manageable after handover?','[{"id":"a","text":"An attractive benefit statement without any measurement."},{"id":"b","text":"A named operational owner, baseline, measure and agreed review point."},{"id":"c","text":"A rule that project installation counts as proof of every benefit."},{"id":"d","text":"A decision to wait until closure before defining the intended improvement."}]'::jsonb,'b','Benefits need ownership and a way to compare actual improvements with expectations. Delivering an output supports value but does not prove it; vague claims and late definition make evaluation difficult.')
