values('stakeholder-engagement-01','stakeholder-engagement',2,'4.6','An affected passenger group has little formal influence over a station redesign. What should the manager do?','[{"id":"a","text":"Exclude the group because only funding authority matters."},{"id":"b","text":"Assess its needs and impacts and choose proportionate engagement."},{"id":"c","text":"Assume a general announcement provides all necessary engagement."},{"id":"d","text":"Ask the group to approve the supplier’s entire commercial contract."}]'::jsonb,'b','Stakeholder analysis considers effects and needs as well as formal influence. The group may hold valuable information or need an accessible involvement route. Neither exclusion nor inappropriate approval duties follows from its low formal power.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('stakeholder-engagement-02','stakeholder-engagement',2,'4.6','Which output shows that stakeholder analysis has informed action?','[{"id":"a","text":"An alphabetical contact list with no further decisions."},{"id":"b","text":"A promise to send every person every document."},{"id":"c","text":"A targeted engagement action, owner and review point based on the group’s concerns."},{"id":"d","text":"A rule that the analysis must never change."}]'::jsonb,'c','Analysis should shape engagement. Contacts alone do not explain needs or actions, and blanket distribution may be unhelpful or inappropriate. Interests, influence and impacts can change during delivery.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('stakeholder-engagement-03','stakeholder-engagement',2,'4.6','A new operator joins the project and changes how the service will be used. What should happen to the stakeholder analysis?','[{"id":"a","text":"Review it and adjust engagement where interests, impacts or responsibilities have changed."},{"id":"b","text":"Archive it immediately because the project has already started."},{"id":"c","text":"Keep it unchanged to preserve an alphabetical order."},{"id":"d","text":"Replace all engagement with a cost estimate."}]'::jsonb,'a','Changed stakeholders and operating assumptions are reasons to revisit analysis. Preserving an obsolete list is not useful control, and cost estimating does not replace engagement planning.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('stakeholder-engagement-04','stakeholder-engagement',2,'4.6','A highly influential stakeholder appears supportive, but the manager has not checked what matters to them. What is the best response?','[{"id":"a","text":"Explore their interests and expectations before deciding the engagement approach."},{"id":"b","text":"Assume influence proves permanent support."},{"id":"c","text":"Remove them from analysis because supportive people need no attention."},{"id":"d","text":"Send them every technical record without asking about their information needs."}]'::jsonb,'a','Analysis should be based on understanding rather than an unchecked label. Interests and support can change. Neither exclusion nor indiscriminate distribution is a reliable engagement strategy.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('stakeholder-engagement-05','stakeholder-engagement',2,'4.6','An engagement plan contains workshops and named owners. How should the manager judge whether it is working?','[{"id":"a","text":"Count invitations only and assume understanding follows."},{"id":"b","text":"Stop listening once the initial plan is approved."},{"id":"c","text":"Measure success solely by how many documents were distributed."},{"id":"d","text":"Check whether relevant concerns are understood, addressed and reflected in decisions or agreed actions."}]'::jsonb,'d','Engagement aims at a useful working relationship and informed decisions. Attendance and distribution figures can be supporting evidence, but they do not establish that concerns or commitments have been handled.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('communication-01','communication',2,'9.1','A report was sent successfully, but its recipient misunderstood the decision required. What best explains the gap?','[{"id":"a","text":"Communication is complete as soon as a file is sent."},{"id":"b","text":"The report must contain more pages, regardless of purpose."},{"id":"c","text":"The recipient should be removed from the stakeholder list."},{"id":"d","text":"Transmission occurred, but shared understanding and feedback were not established."}]'::jsonb,'d','Communication involves meaning and understanding, not only delivery of data. Clarification and feedback may be needed. More pages or exclusion do not automatically solve the misunderstanding.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('communication-02','communication',2,'9.4','Which information belongs in a communication-plan entry?','[{"id":"a","text":"Only a colour for the report cover."},{"id":"b","text":"Audience, purpose/content, method, timing, owner and feedback route."},{"id":"c","text":"Only the total project budget."},{"id":"d","text":"A permanent promise to use one method for every audience."}]'::jsonb,'b','A useful entry connects the audience’s information need with practical delivery and feedback arrangements. A budget or document appearance alone cannot coordinate communication, and methods should fit different purposes.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('communication-03','communication',2,'9.3','Which is a realistic disadvantage of virtual communication for a dispersed team?','[{"id":"a","text":"It is impossible to share a document virtually."},{"id":"b","text":"It always requires physical travel."},{"id":"c","text":"Technology access, time zones and missing non-verbal cues can hinder understanding."},{"id":"d","text":"It guarantees that every participant understands immediately."}]'::jsonb,'c','Virtual methods can improve reach while introducing access, timing and interpretation challenges. They can share documents and reduce travel, but no channel guarantees understanding.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('communication-04','communication',2,'9.2','For a sensitive disagreement requiring rapid clarification, what is a useful advantage of a face-to-face discussion?','[{"id":"a","text":"It automatically creates a complete written audit trail."},{"id":"b","text":"It allows immediate questions and richer non-verbal feedback."},{"id":"c","text":"It guarantees that everyone can attend without travel."},{"id":"d","text":"It removes the need to record agreed decisions."}]'::jsonb,'b','Direct discussion can support clarification and interpretation through immediate and non-verbal feedback. It may still require travel, and important decisions should be recorded rather than assuming the conversation is its own complete record.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('communication-05','communication',2,'9.5','How does an agreed communication plan benefit the project manager?','[{"id":"a","text":"It makes all stakeholders require identical information."},{"id":"b","text":"It prevents communication needs changing during delivery."},{"id":"c","text":"It clarifies responsibilities and timing, reducing gaps and unnecessary duplication."},{"id":"d","text":"It guarantees that a sent message has been understood without feedback."}]'::jsonb,'c','A plan coordinates who communicates what, when and how. It needs review as audiences and needs change, and it does not replace checking understanding or tailoring information.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
