values('scope-management-02','scope-management',2,'5.6','A drawing is labelled with a new version number. What must still be established before an associated scope change is implemented?','[{"id":"a","text":"That every previous file has been printed."},{"id":"b","text":"That the version number is longer than the old one."},{"id":"c","text":"That the change has been evaluated and authorised through the agreed change process."},{"id":"d","text":"That configuration management can replace all governance decisions."}]'::jsonb,'c','Configuration identification does not authorise a change. Change control provides the impact assessment and approval decision; configuration management then helps maintain reliable approved versions and status.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
