insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('resource-scheduling-05','resource-scheduling',2,'6.4','A team commits to a two-week delivery timebox. What does timeboxing mean?','[{"id":"a","text":"Every idea must be delivered even if the period needs indefinite extension."},{"id":"b","text":"No priorities or acceptance conditions may be discussed."},{"id":"c","text":"All project phases must last exactly two weeks."},{"id":"d","text":"Work is managed within a fixed period, with scope or priority handled through agreed rules."}]'::jsonb,'d','The fixed period is the defining feature. Teams still need prioritisation, acceptance and controls. Extending every timebox until everything is finished removes the constraint the technique is intended to provide.')
