values('information-and-reporting-01','information-and-reporting',2,'4.11','Eight of ten units are installed, but only four have passed acceptance tests. What should a useful report do?','[{"id":"a","text":"Call all eight accepted to maintain a green status."},{"id":"b","text":"Show installation only and omit the reporting date."},{"id":"c","text":"Distinguish installation from acceptance and explain the forecast impact."},{"id":"d","text":"Avoid mentioning the issue until every test is finished."}]'::jsonb,'c','Different completion states need clear evidence and a reporting date. Explaining the effect on the remaining work supports decisions. Re-labelling or concealing the gap gives a misleading picture.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('information-and-reporting-02','information-and-reporting',2,'4.11','What most improves a sponsor report about a forecast delay?','[{"id":"a","text":"A clear explanation of impact, options and the decision required from the sponsor."},{"id":"b","text":"More pages of unfiltered activity logs regardless of relevance."},{"id":"c","text":"Removing uncertainty from the wording even when evidence is incomplete."},{"id":"d","text":"Replacing the approved baseline with the forecast without approval."}]'::jsonb,'a','The sponsor needs timely decision-quality information. Volume is not a substitute for relevance, uncertainty should be honest, and the baseline must remain a controlled reference.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('information-and-reporting-03','information-and-reporting',2,'4.11','Why should reports distinguish actual performance from forecast performance?','[{"id":"a","text":"Because forecasts must never change."},{"id":"b","text":"Because actual spending proves the final cost automatically."},{"id":"c","text":"Because recipients should never question assumptions."},{"id":"d","text":"Because what has happened and what is now expected answer different control questions."}]'::jsonb,'d','Actuals describe performance to a reporting date; forecasts describe the expected future position. Both are useful and neither removes the need to examine assumptions, remaining work or the authorised baseline.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('information-and-reporting-04','information-and-reporting',2,'4.11','A project is currently under budget but has substantial uncompleted work and a known fault. Which reporting approach best supports control?','[{"id":"a","text":"Report only the favourable current expenditure figure."},{"id":"b","text":"Show actuals, remaining-work assumptions and an updated forecast against the authorised baseline."},{"id":"c","text":"Assume that underspending now guarantees a favourable final cost."},{"id":"d","text":"Remove the fault from the report until its replacement cost is certain."}]'::jsonb,'b','Actual expenditure alone does not establish the expected final position. Forecast assumptions and known issues help stakeholders understand consequences and decisions. Uncertainty should be explained rather than concealed.')
on conflict(id) do update set content_version=excluded.content_version,syllabus_ref=excluded.syllabus_ref,stem=excluded.stem,choices=excluded.choices,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation where current.content_version<=excluded.content_version;
insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('information-and-reporting-05','information-and-reporting',2,'4.11','Why should a progress report name the owner and due date of an agreed corrective action?','[{"id":"a","text":"To make the baseline unnecessary."},{"id":"b","text":"To guarantee that no further issue will arise."},{"id":"c","text":"To make follow-up and accountability clear."},{"id":"d","text":"To ensure that every stakeholder receives all confidential detail."}]'::jsonb,'c','An action needs responsibility and a review point to be managed. This supports follow-up but does not eliminate uncertainty, replace the baseline or justify excessive distribution of sensitive information.')
