insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('leadership-and-teamwork-04','leadership-and-teamwork',2,'10.1','Which statement best describes leadership in a project?','[{"id":"a","text":"Creating direction and helping people work towards a shared purpose."},{"id":"b","text":"Using formal authority as a substitute for every conversation."},{"id":"c","text":"Performing all specialist work personally."},{"id":"d","text":"Removing the need for agreed responsibilities."}]'::jsonb,'a','Leadership concerns direction and influence as well as support for collective work. Authority alone does not create commitment, and a leader does not need to replace specialist contributions or role clarity.')
