insert into apm_private.checkpoint_questions as current (id,lesson_id,content_version,syllabus_ref,stem,choices,correct_option_id,explanation)
values('leadership-and-teamwork-05','leadership-and-teamwork',2,'10.3','A dispersed team has conflicting functional priorities and uneven experience. What is an appropriate leadership response?','[{"id":"a","text":"Assume that one message and one support style will suit everyone."},{"id":"b","text":"Treat every request for help as evidence of poor commitment."},{"id":"c","text":"Ignore functional conflicts because the team is temporary."},{"id":"d","text":"Clarify priorities and responsibilities, adapt support and agree workable communication."}]'::jsonb,'d','These are practical team-development challenges. Clear agreements, listening and proportionate support can improve collaboration; ignoring differences or discouraging concerns can hide problems.')
